   723  /*
   724   * Note a second interface that returns a bam pointer instead would avoid bam_copy1
   725   * in multi-threaded handling.  This may be worth considering for htslib2.
   726   */
   727  int bam_read1(BGZF *fp, bam1_t *b)
   728  {
   729      bam1_core_t *c = &b->core;
   730      int32_t block_len, ret, i;
   731      uint32_t x[8], new_l_data;
   732
   733      b->l_data = 0;
   734
   735      if ((ret = bgzf_read(fp, &block_len, 4)) != 4) {
   736          if (ret == 0) return -1; // normal end-of-file
   737          else return -2; // truncated
   738      }
   739      if (fp->is_be)
   740          ed_swap_4p(&block_len);
   741      if (block_len < 32) return -4;  // block_len includes core data
   742      if (bgzf_read(fp, x, 32) != 32) return -3;
   743      if (fp->is_be) {
   744          for (i = 0; i < 8; ++i) ed_swap_4p(x + i);
   745      }
   746      c->tid = x[0]; c->pos = (int32_t)x[1];
   747      c->bin = x[2]>>16; c->qual = x[2]>>8&0xff; c->l_qname = x[2]&0xff;
   748      c->l_extranul = (c->l_qname%4 != 0)? (4 - c->l_qname%4) : 0;
   749      c->flag = x[3]>>16; c->n_cigar = x[3]&0xffff;
   750      c->l_qseq = x[4];
   751      c->mtid = x[5]; c->mpos = (int32_t)x[6]; c->isize = (int32_t)x[7];
   752
   753      new_l_data = block_len - 32 + c->l_extranul;
   754      if (new_l_data > INT_MAX || c->l_qseq < 0 || c->l_qname < 1) return -4;
   755      if (((uint64_t) c->n_cigar << 2) + c->l_qname + c->l_extranul
   756          + (((uint64_t) c->l_qseq + 1) >> 1) + c->l_qseq > (uint64_t) new_l_data)
   757          return -4;
   758      if (realloc_bam_data(b, new_l_data) < 0) return -4;
   759      b->l_data = new_l_data;
   760
   761      if (bgzf_read(fp, b->data, c->l_qname) != c->l_qname) return -4;
   762      if (b->data[c->l_qname - 1] != '\0') { // Try to fix missing NUL termination
   763          if (fixup_missing_qname_nul(b) < 0) return -4;
   764      }
   765      for (i = 0; i < c->l_extranul; ++i) b->data[c->l_qname+i] = '\0';
   766      c->l_qname += c->l_extranul;
   767      if (b->l_data < c->l_qname ||
   768          bgzf_read(fp, b->data + c->l_qname, b->l_data - c->l_qname) != b->l_data - c->l_qname)
   769          return -4;
   770      if (fp->is_be) swap_data(c, b->l_data, b->data, 0);
   771      if (bam_tag2cigar(b, 0, 0) < 0)
   772          return -4;
   773
   774      if (c->n_cigar > 0) { // recompute "bin" and check CIGAR-qlen consistency
   775          hts_pos_t rlen, qlen;
   776          bam_cigar2rqlens(c->n_cigar, bam_get_cigar(b), &rlen, &qlen);
   777          if ((b->core.flag & BAM_FUNMAP) || rlen == 0) rlen = 1;
   778          b->core.bin = hts_reg2bin(b->core.pos, b->core.pos + rlen, 14, 5);
   779          // Sanity check for broken CIGAR alignments
   780          if (c->l_qseq > 0 && !(c->flag & BAM_FUNMAP) && qlen != c->l_qseq) {
   781              hts_log_error("CIGAR and query sequence lengths differ for %s",
   782                      bam_get_qname(b));
   783              return -4;
   784          }
   785      }
   786
   787      return 4 + block_len;
   788  }
