   858  /*
   859   * Write a BAM file and append to the in-memory index simultaneously.
   860   */
   861  static int bam_write_idx1(htsFile *fp, const sam_hdr_t *h, const bam1_t *b) {
   862      BGZF *bfp = fp->fp.bgzf;
   863
   864      if (!fp->idx)
   865          return bam_write1(bfp, b);
   866
   867      uint32_t block_len = b->l_data - b->core.l_extranul + 32;
   868      if (bgzf_flush_try(bfp, 4 + block_len) < 0)
   869          return -1;
   870      if (!bfp->mt)
   871          hts_idx_amend_last(fp->idx, bgzf_tell(bfp));
   872      else
   873          bgzf_idx_amend_last(bfp, fp->idx, bgzf_tell(bfp));
   874
   875      int ret = bam_write1(bfp, b);
   876      if (ret < 0)
   877          return -1;
   878
   879      if (bgzf_idx_push(bfp, fp->idx, b->core.tid, b->core.pos, bam_endpos(b), bgzf_tell(bfp), !(b->core.flag&BAM_FUNMAP)) < 0) {
   880          hts_log_error("Read '%s' with ref_name='%s', ref_length=%"PRIhts_pos", flags=%d, pos=%"PRIhts_pos" cannot be indexed",
   881                  bam_get_qname(b), sam_hdr_tid2name(h, b->core.tid), sam_hdr_tid2len(h, b->core.tid), b->core.flag, b->core.pos+1);
   882          ret = -1;
   883      }
   884
   885      return ret;
   886  }
