   888  /*
   889   * Set the qname in a BAM record
   890   */
   891  int bam_set_qname(bam1_t *rec, const char *qname)
   892  {
   893      if (!rec) return -1;
   894      if (!qname || !*qname) return -1;
   895
   896      size_t old_len = rec->core.l_qname;
   897      size_t new_len = strlen(qname) + 1;
   898      if (new_len < 1 || new_len > 255) return -1;
   899
   900      int extranul = (new_len%4 != 0) ? (4 - new_len%4) : 0;
   901
   902      size_t new_data_len = rec->l_data - old_len + new_len + extranul;
   903      if (realloc_bam_data(rec, new_data_len) < 0) return -1;
   904
   905      // Make room
   906      if (new_len + extranul != rec->core.l_qname)
   907          memmove(rec->data + new_len + extranul, rec->data + rec->core.l_qname, rec->l_data - rec->core.l_qname);
   908      // Copy in new name and pad if needed
   909      memcpy(rec->data, qname, new_len);
   910      int n;
   911      for (n = 0; n < extranul; n++) rec->data[new_len + n] = '\0';
   912
   913      rec->l_data = new_data_len;
   914      rec->core.l_qname = new_len + extranul;
   915      rec->core.l_extranul = extranul;
   916
   917      return 0;
   918  }
